    "correctAnswer": "$2.51\\text{ mm}$ ($2.51 \\times 10^{-3}\\text{ m}$)",
    "correctIndex": 2,
    "hintEn": "$z_R = \\pi w_0^2 / \\lambda$. Square $w_0$ carefully.",
    "hintAr": "طبق $z_R = \\pi w_0^2 / \\lambda$ مع تربيع نصف القطر.",
    "stepByStepSolutionEn": [
      "$z_R = \\frac{\\pi \\times (2.0 \\times 10^{-5}\\text{ m})^2}{5.0 \\times 10^{-7}\\text{ m}} = \\frac{3.1416 \\times 4.0 \\times 10^{-10}}{5.0 \\times 10^{-7}} = 2.513 \\times 10^{-3}\\text{ m} = 2.51\\text{ mm}$."
    ],
    "stepByStepSolutionAr": [
      "$z_R = \\frac{\\pi \\times (20 \\times 10^{-6})^2}{500 \\times 10^{-9}} = 2.51 \\times 10^{-3}\\text{ m} = 2.51\\text{ mm}$."
    ],
    "teacherTipEn": "This means the beam remains tightly focused over a depth of $2z_R \\approx 5\\text{ mm}$.",
    "teacherTipAr": "يعني هذا أن الحزمة تحافظ على تركيزها البؤري عبر عمق تشغيل قدره نحو 5 ملم."
