    "titleEn": "Gain Saturation in a Laser Active Medium",
    "titleAr": "تشبع الكسب في الوسط الفعال لليزر",
    "difficulty": "medium",
    "questionEn": "In an actively lasing medium, as intracavity optical intensity $I$ increases, the saturated gain coefficient $g(I)$ decreases according to:",
