    "difficulty": "medium",
    "questionEn": "A semiconductor stripe-geometry laser diode has a threshold current density of $J_{\\text{th}} = 1500\\text{ A/cm}^2$. If the active stripe dimensions are width $w = 10\\ \\mu\\text{m}$ ($1.0 \\times 10^{-3}\\text{ cm}$) and cavity length $L = 300\\ \\mu\\text{m}$ ($3.0 \\times 10^{-2}\\text{ cm}$), the threshold current $I_{\\text{th}}$ is:",
