    "difficulty": "medium",
    "questionEn": "A laser diode emits $P_1 = 5.0\\text{ mW}$ at an operating current of $I_1 = 50\\text{ mA}$, and $P_2 = 25.0\\text{ mW}$ when current increases to $I_2 = 75\\text{ mA}$ above threshold. What is the slope efficiency $\\eta_{\\text{slope}} = \\frac{\\Delta P}{\\Delta I}$?",
    "questionAr": "يخرج دايود ليزر قدرة $P_1 = 5.0\\text{ mW}$ عند تيار تشغيل $I_1 = 50\\text{ mA}$، وتزداد القدرة إلى $P_2 = 25.0\\text{ mW}$ عندما يرتفع التيار إلى $I_2 = 75\\text{ mA}$ فوق العتبة. ما كفاءة الميل $\\eta_{\\text{slope}} = \\frac{\\Delta P}{\\Delta I}$؟",
