    "hintEn": "Off-resonance: waves burn two holes in velocity distribution ($+v_z$ and $-v_z$). At resonance: they compete for the single $v_z = 0$ group.",
    "hintAr": "بعيداً عن المركز: تحفر الحزمتان مجموعتين مختلفتين من الذرات ($\\pm v_z$). عند المركز: تتنافسان على ذرات $v_z = 0$ فيتشبع الكسب بشدة.",
